import{z as f,x as d,o as r,c as m,q as o,j as i,D as E,d as n,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Huffman 编码","description":"","frontmatter":{"title":"Huffman 编码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/huffman-coding.md","filePath":"cs/huffman-coding.md","lastUpdated":1791063341000}'),p={name:"cs/huffman-coding.md"};function B(u,a,A,h,C,c){const t=d("Mermaid");return r(),m("div",null,[a[2]||(a[2]=o('<h1 id="huffman-编码" tabindex="-1">Huffman 编码 <a class="header-anchor" href="#huffman-编码" aria-label="Permalink to &quot;Huffman 编码&quot;">​</a></h1><div class="epigraph"><p>每次合并两个最轻的权，得到的前缀码在整数码长、逐符号意义下期望最短；它逼近熵，但不拆开一个符号内部的比特。</p><footer>—— 据 Huffman, A Method for the Construction of Minimum-Redundancy Codes, 1952；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/source-coding-theorem">信源编码定理</a> 给出 \\(H\\le L\\lt H+1\\) 的空间。缺口是构造：<strong>Huffman 算法</strong>达到所有前缀码中最小的 \\(L=\\sum p_i\\ell_i\\)。不重证 Kraft，不写算术（下一课才把码长变成分数比特）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>已知有限字母表与 \\(p_i\\gt 0\\)。前缀码 \\(\\iff\\) 二叉树叶。期望长度 = 加权路径长。Huffman：把最小的两权合成一父节点，权相加，递归。最优性：存在最优码使两最小符号互为兄弟，故归纳成立。码长 \\(\\ell_i=\\lceil-\\log p_i\\rceil\\) 的 Shannon 码未必最优，Huffman 才是。</p><p><span class="marginnote">直觉类比：摩斯电码里 E 是「·」、I 是「··」，必须靠停顿断字，否则歧义；前缀码把「任何码字都不是另一个的开头」写进构造——收到 110，走到叶就交符号立刻回头，像一棵每个出口都挂了名牌的迷宫，不需要任何分隔符与停顿。</span></p><p>当某 \\(p_i\\) 很大，\\(L\\) 仍 \\(\\ge 1\\cdot p_{\\max}\\)，离 \\(H\\) 可差近 1。这是「不拆符号」的代价，留给算术编码。</p><h3 id="不是「频繁的字母用短-ascii」" tabindex="-1">不是「频繁的字母用短 ASCII」 <a class="header-anchor" href="#不是「频繁的字母用短-ascii」" aria-label="Permalink to &quot;不是「频繁的字母用短 ASCII」&quot;">​</a></h3><p>ASCII 定长。Huffman 相对给定 \\(p\\)；换语料要换树。自适应 Huffman 点名，本课静态。</p><p><span class="marginnote">Huffman 1952。Cover–Thomas 第 5 章证明最优。Kraft 等号：完全树。本课不把堆实现当主线，算法课已有优先队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对小分布手算一棵树，核对 \\(L\\) 与 \\(H\\)。强调：平局时树不唯一，\\(L\\) 相同。译码：从根走比特。不要用哈夫曼树去纠错——距离无保证。</p>',12)),(r(),i(s,null,{default:E(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A6%82%E7%8E%87%E8%A1%A8%22%5D%20--%3E%20MERGE%5B%22%E5%8F%8D%E5%A4%8D%E5%90%88%E5%B9%B6%E4%B8%A4%E6%9C%80%E5%B0%8F%E6%9D%83%22%5D%0A%20%20MERGE%20--%3E%20TREE%5B%22%E5%89%8D%E7%BC%80%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20L%5B%22%E6%9C%9F%E6%9C%9B%E9%95%BF%E5%BA%A6%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"最优前缀码给出可即时译码的比特流，无需逗号。块 Huffman（对 \\(n\\) 元组）把 \\(L/n\\) 推向 \\(H\\)，代价是表指数。实践中宁可用自适应或算术。本课把「整数码长最优」钉死。",-1)),a[5]||(a[5]=e("p",null,[n("与"),e("a",{href:"/cs/regex-lexer"},"词法 DFA"),n(" 无关：那是识别，这是编码。")],-1)),a[6]||(a[6]=e("p",null,"兄弟性质：最稀的两个符号在最优树里深度相同且为兄弟，故贪心合并合法。规范 Huffman 只存码长，译码表更紧，本课不写比特格式。\\(p_i\\) 为 \\(2\\) 的负幂时 \\(L=H\\)。否则整数码长是网格，算术下一课拆开格子。",-1)),a[7]||(a[7]=e("p",null,"译码器为什么不需要逗号也不会歧义？顺着比特从根往下走：",-1)),(r(),i(s,null,{default:E(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E8%AF%BB%E4%B8%8B%E4%B8%80%E6%AF%94%E7%89%B9%22%5D%20--%3E%20W%7B%22%E4%BB%8E%E5%BD%93%E5%89%8D%E8%8A%82%E7%82%B9%E8%B5%B0%E5%87%BA%E4%B8%80%E6%AD%A5%22%7D%0A%20%20W%20--%3E%7C%22%E8%90%BD%E5%9C%A8%E5%86%85%E9%83%A8%E8%8A%82%E7%82%B9%22%7C%20B%0A%20%20W%20--%3E%7C%22%E5%88%B0%E8%BE%BE%E5%8F%B6%22%7C%20OUT%5B%22%E8%BE%93%E5%87%BA%E8%AF%A5%E7%AC%A6%E5%8F%B7%EF%BC%8C%E5%9B%9E%E5%88%B0%E6%A0%B9%22%5D%0A%20%20OUT%20--%3E%20DONE%7B%22%E6%B5%81%E6%B2%A1%E7%BB%93%E6%9D%9F%EF%BC%9F%22%7D%0A%20%20DONE%20--%3E%7C%22%E6%98%AF%22%7C%20B%0A%20%20DONE%20--%3E%7C%22%E5%90%A6%22%7C%20END%5B%22%E8%AF%91%E7%A0%81%E5%AE%8C%E6%88%90%EF%BC%8C%E6%97%A0%E9%9C%80%E4%BB%BB%E4%BD%95%E5%88%86%E9%9A%94%E7%AC%A6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：分布 \\(\\{1/2,\\,1/4,\\,1/8,\\,1/8\\}\\) 给出码长 \\(\\{1,2,3,3\\}\\)，\\(L=1/2+2/4+3/8+3/8=1.75\\)，恰好等于熵 \\(H=1.75\\)——每一步都是 2 的负幂概率时，整数码长能精确触到熵。一旦概率不是 2 的负幂（如 \\(1/3\\)），只能取整，\\(L\\) 就比 \\(H\\) 多出零点几比特。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证算术，不引入规范 Huffman 的比特级格式。不把 JPEG 的表当定义。后课默认：逐符号前缀最优 = Huffman；分数比特下一课。下一课算术编码。</p><p>最优是相对前缀码与给定 \\(p\\) 的期望长度，不是相对算术码，也不是相对 \\(K(x)\\)。换语料必须换树或改成自适应。纠错不要用这棵树的码字距离。</p><p><span class="marginnote">常见误区：初学者容易想拿哈夫曼码「顺便纠错」。它的优化目标只有平均长度最短，码字之间的距离没有任何保证——一个比特翻转就可能落进另一条全然不同的路径，译出看似合法的错符号。要抗错得上校验或专门的纠错码，压缩与纠错是两本账。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Huffman 合并最小权，得到最优前缀码。</li><li>\\(L\\) 仍可能比 \\(H\\) 差近 1；块或算术再逼近。</li><li>相对给定分布；不是字符集。</li><li>出处：Huffman, 1952；Cover and Thomas。</li></ul>',7))])}const H=f(p,[["render",B]]);export{_ as __pageData,H as default};
